<?php

namespace App\Http\Controllers\Api\Ai;

use App\Http\Controllers\Controller;
use App\Models\Page;
use App\Models\Space;
use App\Services\Ai\AiAssistant;
use App\Services\Knowledgebase\PageAcl;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Throwable;

/**
 * "Ask the knowledge base" assistant. Answers are generated by a local Ollama
 * model over content the user is allowed to see.
 */
class AssistantController extends Controller
{
    public function __construct(private readonly AiAssistant $assistant)
    {
    }

    public function status(): JsonResponse
    {
        return response()->json([
            'data' => [
                'enabled' => $this->assistant->enabled(),
                'model' => $this->assistant->model(),
            ],
        ]);
    }

    public function ask(Request $request): JsonResponse
    {
        if (! $this->assistant->enabled()) {
            return response()->json([
                'message' => 'AI-ассистент не настроен (задайте AI_ENABLED=true и OLLAMA_URL)',
            ], 503);
        }

        $validated = $request->validate([
            'question' => 'required|string|min:2|max:2000',
            'types' => 'sometimes|array',
            'types.*' => 'in:' . implode(',', AiAssistant::ALLOWED_TYPES),
        ]);

        try {
            $result = $this->assistant->ask(
                $request->user(),
                $validated['question'],
                $validated['types'] ?? [],
            );
        } catch (Throwable $e) {
            return response()->json([
                'message' => 'Не удалось получить ответ: ' . $e->getMessage(),
            ], 503);
        }

        return response()->json(['data' => $result]);
    }

    /** Summarize a knowledgebase page (ACL-checked). */
    public function summarize(Request $request): JsonResponse
    {
        if (! $this->assistant->enabled()) {
            return $this->disabled();
        }

        $validated = $request->validate([
            'page_id' => 'required|integer|exists:pages,id',
        ]);

        $page = Page::findOrFail((int) $validated['page_id']);
        $space = Space::find($page->space_id);
        $user = $request->user();

        if ($space === null
            || ! Space::whereKey($space->id)->visibleTo($user)->exists()
            || ! PageAcl::for($space, $user)->canView($page)) {
            abort(404, 'Страница не найдена');
        }

        try {
            $summary = $this->assistant->summarize((string) $page->title, Page::plainText((string) $page->body));
        } catch (Throwable $e) {
            return response()->json(['message' => 'Не удалось получить резюме: ' . $e->getMessage()], 503);
        }

        return response()->json([
            'data' => [
                'page_id' => (int) $page->id,
                'summary' => $summary,
                'model' => $this->assistant->model(),
            ],
        ]);
    }

    /** Generate a task or email draft from a short prompt. */
    public function draft(Request $request): JsonResponse
    {
        if (! $this->assistant->enabled()) {
            return $this->disabled();
        }

        $validated = $request->validate([
            'kind' => 'required|in:task,mail',
            'prompt' => 'required|string|min:3|max:2000',
        ]);

        try {
            $text = $this->assistant->draft($validated['kind'], $validated['prompt']);
        } catch (Throwable $e) {
            return response()->json(['message' => 'Не удалось сгенерировать черновик: ' . $e->getMessage()], 503);
        }

        return response()->json([
            'data' => [
                'kind' => $validated['kind'],
                'draft' => $text,
                'model' => $this->assistant->model(),
            ],
        ]);
    }

    private function disabled(): JsonResponse
    {
        return response()->json([
            'message' => 'AI-ассистент не настроен (задайте AI_ENABLED=true и OLLAMA_URL)',
        ], 503);
    }
}
